package com.xdownload.mobile;import org.junit.Test;import static org.junit.Assert.*;import java.io.*;public class ActualDuplicatesTest{@Test public void hashBytes()throws Exception{String a=ActualDuplicates.hash(new ByteArrayInputStream(new byte[]{1,2}),2,()->true);assertEquals(a,ActualDuplicates.hash(new ByteArrayInputStream(new byte[]{1,2}),2,()->true));assertNotEquals(a,ActualDuplicates.hash(new ByteArrayInputStream(new byte[]{1,3}),2,()->true));try{ActualDuplicates.hash(new ByteArrayInputStream(new byte[]{1,2}),1,()->true);fail();}catch(IOException expected){}}}